private void run()
{
    RetailPeriodicDiscountLine periodicDiscountLineNew;
    MultiSelectionHelper selectionHelper = MultiSelectionHelper::construct();

    selectionHelper.parmDataSource(periodicDiscountLine_ds);

    try
    {
        ttsbegin;

        RetailPeriodicDiscountLine periodicDiscountLineOrig = selectionHelper.getFirst();
        while (periodicDiscountLineOrig)
        {
            periodicDiscountLineOrig.copyRetailPeriodicDiscountLine(true);
            periodicDiscountLineOrig = selectionHelper.getNext();
        }

        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::Error)
    {
        ttsabort;
        Box::stop("@GLS110288");
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

private FormDataSource formDataSource(FormDataSource _periodicDiscountLine_ds = periodicDiscountLine_ds)
{
    periodicDiscountLine_ds = _periodicDiscountLine_ds;

    return periodicDiscountLine_ds;
}

public static void main(Args _args)
{
    GUPPeriodicDiscountLineCopy periodicDiscountLineCopy = new GUPPeriodicDiscountLineCopy();

    if (_args && _args.record() && _args.record() is RetailPeriodicDiscountLine)
    {
        FormDataSource periodicDiscountLine_ds = FormDataUtil::getFormDataSource(_args.record());

        periodicDiscountLineCopy.formDataSource(periodicDiscountLine_ds);
        periodicDiscountLineCopy.run();

        FormRun formRun = _args.caller();

        if(formRun)
        {
            if (formRun.dataSource(tableStr(RetailPeriodicDiscount)))
            {
                FormDataSource formDS = formRun.dataSource(tableStr(RetailPeriodicDiscount));
                formDS.research(true);
            }
        }
    }
    else
    {
        throw error(strFmt("@SYS27147", new DictClass(classIdGet(periodicDiscountLineCopy)).name()));
    }
}
